package com.mmpantry.app;
import android.app.*;import android.os.*;import android.widget.*;
public class RecipeDetailActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);DatabaseHelper db=new DatabaseHelper(this);Recipe r=db.getRecipe(getIntent().getIntExtra("id",-1));LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(30,30,30,20);l.setBackgroundColor(Ui.background(this));TextView h=Ui.text(this,r==null?"Recipe unavailable":r.name,30);l.addView(h);if(r!=null){TextView d=Ui.text(this,r.description+"\n\nIngredients",17);l.addView(d);for(Recipe.Req x:r.ingredients){TextView t=Ui.text(this,"• "+x.name+" — "+x.qty+" "+x.unit,16);l.addView(t);}TextView m=Ui.text(this,"\nMethod\n"+r.method,17);l.addView(m);}setContentView(l);}}
